<script setup>import AppShell from'../Layouts/AppShell.vue';import{Head,Link}from'@inertiajs/vue3';defineProps({stats:Object,groups:Array,recent:Array})</script><template><AppShell><Head title="Dashboard"/><div class="flex flex-wrap items-end justify-between gap-4"><div><p class="eyebrow">Studio overview</p><h1 class="mt-2 font-display text-3xl font-bold">Your creative control room</h1></div><a v-if="$page.props.permissions?.createGroups" href="/groups/create" class="btn-primary">Create Group</a></div><section class="mt-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><div v-for="(v,k) in stats" :key="k" class="panel p-5"><p class="text-sm capitalize text-black/45">{{k.replace('_',' ')}}</p><p class="mt-2 font-display text-3xl font-bold">{{v}}</p></div></section><section class="mt-8"><div class="mb-4 flex justify-between"><h2 class="font-display text-xl font-bold">Active Groups</h2><Link href="/groups" class="text-sm font-semibold text-indigo">View all</Link></div><div class="grid gap-5 md:grid-cols-2 xl:grid-cols-3"><Link v-for="group in groups" :key="group.id" :href="`/groups/${group.id}`" class="panel overflow-hidden transition hover:-translate-y-0.5"><div class="h-32 bg-gradient-to-br from-ink via-indigo/80 to-coral/60"></div><div class="p-5"><h3 class="font-display text-lg font-bold">{{group.name}}</h3><p class="mt-2 text-sm text-black/45">{{group.photos_count}} photos · {{group.members_count}} participants</p></div></Link></div></section></AppShell></template>
